-- LYN4X Miku Galaxy V1 | Delta local skybox
-- Six PNG faces embedded. No external image URLs needed.
-- Requires executor support for writefile + getcustomasset/getsynasset.
local Lighting = game:GetService("Lighting")
local HttpService = game:GetService("HttpService")
local asset = getcustomasset or getsynasset
if type(writefile) ~= "function" or type(asset) ~= "function" then
    warn("[LYN4X SKY] This executor needs writefile and getcustomasset (or getsynasset) to use embedded PNG skyboxes.")
    return
end
local images = {
    Bk = [[]],
    Ft = [[]],
    Lf = [[]],
    Rt = [[]],
    Up = [[]],
    Dn = [[]],
}
local ids = {}
for face, encoded in pairs(images) do
    local path = "LYN4X_MIKU_GALAXY_V1_" .. face .. ".png"
    local ok, result = pcall(function()
        writefile(path, HttpService:Base64Decode(encoded))
        return asset(path)
    end)
    if not ok or type(result) ~= "string" then
        warn("[LYN4X SKY] Could not load " .. face .. ": " .. tostring(result))
        return
    end
    ids[face] = result
end
local sky = Lighting:FindFirstChild("LYN4X_Miku_Galaxy_V1")
if not sky then
    sky = Instance.new("Sky")
    sky.Name = "LYN4X_Miku_Galaxy_V1"
end
sky.SkyboxBk = ids.Bk
sky.SkyboxFt = ids.Ft
sky.SkyboxLf = ids.Lf
sky.SkyboxRt = ids.Rt
sky.SkyboxUp = ids.Up
sky.SkyboxDn = ids.Dn
for _, child in ipairs(Lighting:GetChildren()) do
    if child:IsA("Sky") and child ~= sky then child:Destroy() end
end
sky.Parent = Lighting
print("[LYN4X SKY] Six faces applied (local client).")
